-- Eleven original identity sources; AUTHORED_NOT_EXECUTED. No source DML or compatibility views.
-- Freeze both schemas in the reviewed migration window; flags assert external evidence, not a write freeze.
-- Strict original column/key/collation/clock/HWM and full-row hash checks. Never --force.
SET NAMES utf8mb4;
SET @compact_identity_previous_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=3200000;
CREATE TEMPORARY TABLE compact_identity_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
INSERT INTO compact_identity_guard SELECT IF(COALESCE((DATABASE() IS NOT NULL AND BINARY DATABASE()<>BINARY '__SOURCE_SCHEMA__' AND @@FOREIGN_KEY_CHECKS=1 AND @compact_identity_source_frozen=1 AND @compact_identity_target_frozen=1 AND @@SESSION.sql_mode REGEXP '(^|,)(STRICT_TRANS_TABLES|STRICT_ALL_TABLES)(,|$)' AND '__SOURCE_IDENTITY_OFFSET__' REGEXP '^[+-][0-9]{2}:[0-9]{2}$' AND CONVERT_TZ('2026-01-01','__SOURCE_IDENTITY_OFFSET__','+00:00') IS NOT NULL),FALSE),1,0);
INSERT INTO compact_identity_guard SELECT IF(COALESCE(((SELECT COUNT(DISTINCT privilege_type) FROM information_schema.schema_privileges WHERE table_schema='__SOURCE_SCHEMA__' AND privilege_type IN ('SELECT','TRIGGER') AND grantee=CONCAT(QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',1)),'@',QUOTE(SUBSTRING_INDEX(CURRENT_USER(),'@',-1))))=2),FALSE),1,0);
